package local.codeleader;

import io.opentelemetry.api.GlobalOpenTelemetry;
import io.opentelemetry.api.trace.*;
import io.opentelemetry.context.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Fixed framework/driver observation points. No extra reads, queries or business serializers. */
public final class BoundaryHelper {
  static final Map<Object,HttpCall> HTTP=Collections.synchronizedMap(new WeakHashMap<>());
  static final Map<Object,SqlState> SQL=Collections.synchronizedMap(new WeakHashMap<>());
  static final Map<Object,JdbcCall> RESULTS=Collections.synchronizedMap(new WeakHashMap<>());
  static boolean enabled(){return "raw".equals(System.getenv("CODELEADER_POLICY"))&&Span.current().getSpanContext().isValid();}
  static Span span(String name,String boundary){return GlobalOpenTelemetry.getTracer("codeleader.boundaries","2").spanBuilder(name).startSpan().setAttribute("codeleader.boundary",boundary).setAttribute("codeleader.version",System.getenv("CODELEADER_VERSION")).setAttribute("codeleader.clock",ValueHelper.PROCESS);}
  public static Object field(Object value,String name)throws Exception{Class<?> type=value.getClass();for(int i=0;type!=null&&i<8;i++,type=type.getSuperclass()){try{Field field=type.getDeclaredField(name);if(field.trySetAccessible())return field.get(value);}catch(NoSuchFieldException ignored){}}return null;}
  static Object headers(Object value){try{if(value!=null&&value.getClass().getName().startsWith("org.springframework.http."))return value.getClass().getMethod("toSingleValueMap").invoke(value);}catch(Throwable ignored){}return Map.of();}
  static boolean textual(Object headers){if(!(headers instanceof Map<?,?> map))return false;for(var e:map.entrySet())if(e.getKey() instanceof String key&&key.equalsIgnoreCase("Content-Type")&&e.getValue() instanceof String type){String lower=type.toLowerCase(Locale.ROOT);return (lower.contains("json")||lower.startsWith("text/"))&&!lower.contains("event-stream");}return false;}
  static String httpSnapshot(Map<String,Object> fields,ByteArrayOutputStream bytes,long total,boolean text,boolean complete){List<String> limits=new ArrayList<>();fields.put("bodyBytesObserved",total);if(!text){fields.remove("body");fields.put("bodyMissing",total==0?"无已观察正文":"二进制、流或未适配的正文类型");fields.put("savedBytes",0);return ValueHelper.actual(fields);}String body=bytes.toString(StandardCharsets.UTF_8),saved=body.substring(0,Math.min(body.length(),8192));int size=saved.getBytes(StandardCharsets.UTF_8).length;fields.put("body",saved);fields.put("savedBytes",size);fields.put("complete",complete);if(size<total)limits.add("{\"path\":\"body\",\"reason\":\"HTTP 正文预算\","+(complete?"\"originalLength\":"+total+",":"")+"\"saved\":"+size+",\"unit\":\"字节\"}");return ValueHelper.actual(fields,limits);}
  public static class HttpCall {public Span span;public Scope scope;public Context context;public String parent;public ByteArrayOutputStream request=new ByteArrayOutputStream(),response=new ByteArrayOutputStream();public Map<String,Object> input=new LinkedHashMap<>(),output=new LinkedHashMap<>();public long requestLength,responseLength;public boolean done,requestText,responseText,eof;}
  public static HttpCall httpEnter(Object request,Object headers){if(!enabled())return null;HttpCall call=new HttpCall();try{call.parent=Span.current().getSpanContext().getSpanId();call.span=span("HTTP payload","http.payload");call.scope=call.span.makeCurrent();call.context=Context.current();Object capturedHeaders=headers(headers);call.input.put("headers",capturedHeaders);call.requestText=textual(capturedHeaders);Object connection=field(request,"connection");if(connection instanceof java.net.HttpURLConnection c){call.span.setAttribute("url.full",c.getURL().toExternalForm()).setAttribute("http.request.method",c.getRequestMethod());}Object uri=field(request,"uri");if(uri instanceof java.net.URI u)call.span.setAttribute("url.full",u.toASCIIString());Object method=field(request,"method");if(method!=null&&method.getClass().getName().equals("org.springframework.http.HttpMethod"))call.span.setAttribute("http.request.method",(String)method.getClass().getMethod("name").invoke(method));return call;}catch(Throwable error){try{if(call.scope!=null)call.scope.close();Span.current().setAttribute("codeleader.capture.http_error",error.getClass().getName());if(call.span!=null)call.span.end();}catch(Throwable ignored){}return null;}}
  public static Object body(Object original,HttpCall call){if(call==null||original==null)return original;try{Class<?> contract=Class.forName("org.springframework.http.StreamingHttpOutputMessage$Body",false,original.getClass().getClassLoader());return Proxy.newProxyInstance(contract.getClassLoader(),new Class<?>[]{contract},new BodyWriter(original,call));}catch(Throwable ignored){call.input.put("bodyMissing","未适配的正文写入器");return original;}}
  public static class BodyWriter implements InvocationHandler {final Object original;final HttpCall call;public BodyWriter(Object original,HttpCall call){this.original=original;this.call=call;}public Object invoke(Object proxy,Method method,Object[] args)throws Throwable{Object[] delegated=args;if(method.getName().equals("writeTo")&&args!=null&&args.length==1&&args[0] instanceof OutputStream output){delegated=args.clone();delegated[0]=new CaptureOutputStream(output,call);}try{return method.invoke(original,delegated);}catch(InvocationTargetException error){throw error.getCause();}}}
  public static class CaptureOutputStream extends FilterOutputStream {final HttpCall call;public CaptureOutputStream(OutputStream output,HttpCall call){super(output);this.call=call;}public void write(int value)throws IOException{out.write(value);try{synchronized(call){call.requestLength++;if(call.requestText&&call.request.size()<131072)call.request.write(value);}}catch(Throwable ignored){}}public void write(byte[] bytes,int offset,int length)throws IOException{out.write(bytes,offset,length);try{synchronized(call){call.requestLength+=length;if(call.requestText)call.request.write(bytes,offset,Math.min(length,Math.max(0,131072-call.request.size())));}}catch(Throwable ignored){}}}
  public static void httpExit(HttpCall call,Object response,Throwable error){if(call==null)return;try{call.scope.close();if(error!=null){call.span.setStatus(StatusCode.ERROR);call.output.put("errorType",error.getClass().getName());httpFinish(call);}else if(response!=null){if(HTTP.size()>1024)HTTP.clear();HTTP.put(response,call);call.input.put("body",call.request.toString(StandardCharsets.UTF_8));call.input.put("bodyBytes",call.requestLength);Span entered=GlobalOpenTelemetry.getTracer("codeleader.boundaries","2").spanBuilder("HTTP payload").setParent(call.context).startSpan();entered.setAttribute("codeleader.phase","enter").setAttribute("codeleader.invocation",call.span.getSpanContext().getSpanId()).setAttribute("codeleader.parent",call.parent).setAttribute("codeleader.boundary","http.payload").setAttribute("codeleader.version",System.getenv("CODELEADER_VERSION")).setAttribute("codeleader.input",httpSnapshot(call.input,call.request,call.requestLength,call.requestText,true));entered.end();try{Object capturedHeaders=headers(Class.forName("org.springframework.http.HttpMessage",false,response.getClass().getClassLoader()).getMethod("getHeaders").invoke(response));call.output.put("headers",capturedHeaders);call.responseText=textual(capturedHeaders);Object status=Class.forName("org.springframework.http.client.ClientHttpResponse",false,response.getClass().getClassLoader()).getMethod("getStatusCode").invoke(response);call.output.put("status",status.getClass().getMethod("value").invoke(status));}catch(Throwable ignored){call.output.put("headersMissing","框架响应元数据不可访问");}}else httpFinish(call);}catch(Throwable ignored){call.span.end();}}
  public static InputStream responseBody(Object response,InputStream stream){HttpCall call=HTTP.get(response);return call==null||stream==null||stream instanceof CaptureInputStream?stream:new CaptureInputStream(stream,call);}
  public static class CaptureInputStream extends FilterInputStream {final HttpCall call;public CaptureInputStream(InputStream input,HttpCall call){super(input);this.call=call;}void keep(byte[] bytes,int offset,int length){try{if(length<0){call.eof=true;httpFinish(call);return;}synchronized(call){call.responseLength+=length;if(call.responseText)call.response.write(bytes,offset,Math.min(length,Math.max(0,131072-call.response.size())));}}catch(Throwable ignored){}}public int read()throws IOException{int value=in.read();if(value<0)keep(new byte[0],0,-1);else keep(new byte[]{(byte)value},0,1);return value;}public int read(byte[] bytes,int offset,int length)throws IOException{int count=in.read(bytes,offset,length);keep(bytes,offset,count);return count;}public void close()throws IOException{try{in.close();}finally{httpFinish(call);}}}
  public static void httpClose(Object response){HttpCall call=HTTP.remove(response);if(call!=null)httpFinish(call);}
  static void httpFinish(HttpCall call){synchronized(call){if(call.done)return;call.done=true;try{call.input.put("body",call.request.toString(StandardCharsets.UTF_8));call.input.put("bodyBytes",call.requestLength);call.input.put("savedBytes",call.request.size());call.output.put("body",call.response.toString(StandardCharsets.UTF_8));call.output.put("bodyBytes",call.responseLength);call.output.put("savedBytes",call.response.size());call.span.setAttribute("codeleader.phase","exit").setAttribute("codeleader.input",httpSnapshot(call.input,call.request,call.requestLength,call.requestText,true)).setAttribute("codeleader.output",httpSnapshot(call.output,call.response,call.responseLength,call.responseText,call.eof));}catch(Throwable ignored){call.span.setAttribute("codeleader.capture.error",true);}finally{try{call.span.end();}catch(Throwable ignored){}}}}
  public static class SqlState {public String template;public Map<String,Object> parameters=new LinkedHashMap<>();public List<Object> batches=new ArrayList<>();public JdbcCall active;}
  public static class JdbcCall {public Span span;public Scope scope;public Map<String,Object> row=new LinkedHashMap<>();public List<Object> rows=new ArrayList<>();public long count,started;public boolean done;}
  public static void prepared(Object statement,Object sql){if(statement==null||!(sql instanceof String text))return;SqlState state=new SqlState();state.template=text;if(SQL.size()>1024)SQL.clear();SQL.put(statement,state);}
  public static void binding(Object statement,String method,Object[] args){SqlState state=SQL.get(statement);if(state==null)return;synchronized(state){if(method.equals("addBatch")){if(state.batches.size()<50)state.batches.add(new LinkedHashMap<>(state.parameters));return;}if(method.equals("clearBatch")){state.batches.clear();return;}if(method.equals("clearParameters")){state.parameters.clear();return;}if(args.length>=2&&args[0] instanceof Integer index&&state.parameters.size()<64)state.parameters.put(String.valueOf(index),method.equals("setNull")?"{\"__codeleader_snapshot\":2,\"value\":null,\"limits\":[]}":ValueHelper.actual(args[1]));}}
  public static JdbcCall jdbcEnter(Object statement){if(!enabled())return null;SqlState state=SQL.get(statement);if(state==null)return null;JdbcCall call=new JdbcCall();call.started=System.nanoTime();call.span=span("SQL execute","jdbc").setAttribute("db.query.text",state.template);Map<String,Object> parameters=new LinkedHashMap<>();synchronized(state){parameters.put("parameters",new LinkedHashMap<>(state.parameters));if(!state.batches.isEmpty())parameters.put("batches",new ArrayList<>(state.batches));state.active=call;}call.span.setAttribute("codeleader.parameters",ValueHelper.actual(parameters));call.scope=call.span.makeCurrent();return call;}
  public static void jdbcExit(Object statement,JdbcCall call,Object result,Throwable error){if(call==null)return;try{call.scope.close();call.span.setAttribute("codeleader.duration_ms",(System.nanoTime()-call.started)/1000000.0);if(error!=null){call.span.setStatus(StatusCode.ERROR);call.span.setAttribute("codeleader.error",ValueHelper.actual(Map.of("type",error.getClass().getName())));jdbcFinish(call);}else if(result instanceof java.sql.ResultSet){RESULTS.put(result,call);}else if(result instanceof Number||result instanceof int[]||result instanceof long[]){call.span.setAttribute("codeleader.output",ValueHelper.actual(Map.of("affectedRows",result)));jdbcFinish(call);}else if(!(result instanceof Boolean flag)||!flag)jdbcFinish(call);}catch(Throwable ignored){call.span.end();}}
  public static void result(Object statement,Object result){SqlState state=SQL.get(statement);if(state!=null&&state.active!=null&&result instanceof java.sql.ResultSet)RESULTS.put(result,state.active);}
  public static void row(Object result,String method,Object[] args,Object value){JdbcCall call=RESULTS.get(result);if(call==null||call.done)return;try{synchronized(call){if(method.equals("next")){if(Boolean.TRUE.equals(value)){if(!call.row.isEmpty()&&call.rows.size()<20)call.rows.add(call.row);call.row=new LinkedHashMap<>();call.count++;}else jdbcFinish(call);}else if(args.length>0&&(args[0] instanceof Integer||args[0] instanceof String)&&call.row.size()<32&&call.count<=20)call.row.put(String.valueOf(args[0]),ValueHelper.actual(value));}}catch(Throwable ignored){}}
  public static void jdbcClose(Object value){JdbcCall call=RESULTS.remove(value);if(call==null){SqlState state=SQL.remove(value);if(state!=null)call=state.active;}if(call!=null)jdbcFinish(call);}
  static void jdbcFinish(JdbcCall call){synchronized(call){if(call.done)return;call.done=true;try{if(!call.row.isEmpty()&&call.rows.size()<20)call.rows.add(call.row);if(call.count>0){List<String> limits=new ArrayList<>();if(call.count>call.rows.size())limits.add("{\"path\":\"savedRows\",\"reason\":\"已观察行的保存预算\",\"originalLength\":"+call.count+",\"saved\":"+call.rows.size()+",\"unit\":\"行\"}");call.span.setAttribute("codeleader.output",ValueHelper.actual(Map.of("observedRows",call.count,"savedRows",call.rows),limits));}}catch(Throwable ignored){call.span.setAttribute("codeleader.capture.error",true);}finally{call.span.end();}}}
}
